Lemma w_bit0 : forall E v w0, bv_unsigned (ev E v) = w0 -> 0 <= w0 < 2 ^ 64 -> alu64 ALU_AND (ext_val false 0 1 (ev E v)) (Z_to_bv 64 1) = Z_to_bv 64 (bit0 w0).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SZ0|600;!1,30|10;!1,02!1,00!2'^034!2+5!2'\,G#2!2'^1#25!1+21!2':1#3}1!1,0,H!2':1:!2':1!1'b=#4!1,0|800;!2'_D#3=!2'^534%~R!2'^1,G3%~R!2'\,G4!2'^1,G5!2'\,G3$Ha;RA$~R+^6!3'^734#2%Ha;RA%~R+^6!2'\,G5!1,T+^8!1+^9+^8!1,^S+B!1+^;+B!1+^=+B!2,^E+B,G!2,^E+B=!2'^LH,^@!4'^M#1#3vv!2,O+=,^N!3+6+=!2'^O#1#3,^N!3'^P+B,G#2!2'_D#4=!2'_S#6=!2'_D#8=%~R!2'\,G#6%~R!2'\,G=!2'\,GO!2,^:+B#2!2,^G+B,H!7,^BH'^>+^?+^?,^@!4,^C+BI,^FR,^H!1,^I+^?!3,^D+B!2,^E+B31!7,^AH'^>+^?+^?,^@S!7,^BH'^>+^?+^?,^@!4,^C+BR,^KU,^H!2'\,G#1!2,^E+B:!2'_W#5#4$E;R+_U$v;R+S$w0;R+B$U;R!3+6+B!2'F1!2'_W#3#2#1$Hw;R6!6'^V78$b;R7!3+67!3'b;,b<!4'b5,?,_[9#1;<!6'^V7!2':1>$b;R7!3+67!3'b;,b<#1;<&H;R!3'b6#3=&__sat2;R?@&__sat1;RBC&__arith;R&__wit;RDE&__varmap;RFG&__ff;R!7,^BH'^>+^?+^?,^@!4,^C+BI,^KJ,^HKL!2'^1,G=#1!2+5!2'\,G>!2'^1>=!6'^V7!2':1!2'b>M:$b;R7!3+67#1!2':1!1'b=#5!2,O7<!3'b;,b<!2':1M;!4'b?M:&__sat3;R?@&__sat2;RBC&__sat1;RNP&__arith;R$__x1;R+B&__wit;RDE&__varmap;RQG&__ff;R!8,^<H'^>+^?+^?,^@!7,^AH'^>+^?+^?,^@S!7,^BH'^>+^?+^?,^@!4,^C+BR,^KJ,^HTVKL%__x1;R+B%~R!2+5W!2'^1#1=6!2#1O#5&__sat3;R?@&__sat2;RBC&__sat1;RNP&__arith;R&__wit;RDE&__varmap;RFG&__ff;R!7,^AH'^>+^?+^?,^@!7,^BH'^>+^?+^?,^@!4,^C+BI,^FX,^H!7,^BH'^>+^?+^?,^@!4,^C+BX,^KU,^HKL!2+5!2'\,G:!2'^1:5#1!4'b5,?,_[98!2'b7#3&__sat2;R?@&__sat1;RBC&__arith;R$__x1;R+B&__wit;RDE&__varmap;RQG&__ff;R!8,^<H'^>+^?+^?,^@VTVKL%__x1;R+B%~R!2+5W!2'^1#156!2#1#6#4Y!3'b8Y#3#2").
