  destruct (Z.eq_dec (bit0 w0) 0) as [B0|NZ].
  - change SBT.R_ASSIGN with (CC.cp_pc GB.cp0).
    ck_open FPM GB.cp0 (GB.plans 0%nat _ eq_refl) (-64) gl (fun _ : nat => @nil byte) (@nil (nat * Z)) sp1 R M fx model K Hh Hl Hfp H2 ck_no_pins.
    + ck_reg E (8%bv : reg) H8.
      ck_gh E 0%nat rav. ck_gh E 1%nat (bv_unsigned (getr R0 8%bv)). ck_gh E 2%nat (bv_unsigned (getr R0 9%bv)). ck_gh E 3%nat (bv_unsigned (getr R0 18%bv)).
      ck_gh E 4%nat (bv_unsigned (getr R0 19%bv)). ck_gh E 5%nat (bv_unsigned (getr R0 20%bv)). ck_gh E 6%nat (bv_unsigned (getr R0 21%bv)).
      ck_gh E 7%nat w0. ck_gh E 8%nat w1. ck_gh E 9%nat w2.
      unfold know_ok, GB.cp0. cbn [CC.cp_know]. repeat (apply Forall_cons); [.. | apply Forall_nil].
      * e_range. * e_align Hal.
      * ck_kw64 (sp1 - 8) rav F1. * ck_kw64 (sp1 - 16) (bv_unsigned (getr R0 8%bv)) F2. * ck_kw64 (sp1 - 24) (bv_unsigned (getr R0 9%bv)) F3.
