      ck_leaf Hag E'.
      assert (FRM : TK.samem (KE4 sp1 SB) M M') by (apply (TK.frame_samem _ _ _ _ _ _ _ HLF); intros a Ha (Hk1 & Hk2 & Hk3); cbn [CC.cp_F]; tk_outside).
